(()=>{'use strict';const form=document.querySelector('#fm');if(!form)return;const project=form.elements.projet,buyer=form.querySelector('.buyer-fields'),message=form.elements.message;const choose=()=>{const buying=project.value==='acheter';buyer.hidden=!buying;buyer.disabled=!buying;message.placeholder=buying?'Vos communes, votre calendrier et les critères importants pour votre recherche…':project.value==='vendre'?'Décrivez votre bien et votre calendrier de vente…':'Votre question…';};project.addEventListener('change',choose);const q=new URLSearchParams(location.search);if(['acheter','vendre','information'].includes(q.get('projet')))project.value=q.get('projet');const ref=q.get('ref');if(ref&&/^r\d+(?:-\d+)?$/.test(ref)){project.value='acheter';form.elements.reference.value=ref;message.value='Je souhaite obtenir des informations et organiser une visite pour le bien '+ref+'.';}choose();form.addEventListener('reset',()=>setTimeout(choose,0));})();
